import{_ as t,o as d,c as o,ag as a}from"./chunks/framework.2EHAL5nC.js";const u=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/configuration.md","filePath":"getting-started/configuration.md","lastUpdated":1793762486000}'),s={name:"getting-started/configuration.md"};function i(n,e,c,r,l,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Configuration is read once, when a command starts, from <code>config/*.toml</code>, <code>.env</code> and the environment. Values that need a deploy to change go here; values admins change at run time go in <a href="./../admin/settings.html">settings</a>.</p><h2 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h2><p>A new application has <code>config/app.toml</code>, <code>auth.toml</code>, <code>http.toml</code> and <code>log.toml</code>, and a <code>.env</code>. Change a value in the file, or override it from the environment:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-NaKDA" id="tab-ME9SR7D" checked><label data-title="config/http.toml" for="tab-ME9SR7D">config/http.toml</label><input type="radio" name="group-NaKDA" id="tab-QOhkS6X"><label data-title="environment" for="tab-QOhkS6X">environment</label></div><div class="blocks"><div class="language-toml vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Maximum request body (bytes) and timeout (seconds).</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">body_limit = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2097152</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">timeout_secs = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30</span></span></code></pre></div><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> RUSTCMS_HTTP__BODY_LIMIT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2097152</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustcms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or for one command: RUSTCMS_HTTP__BODY_LIMIT=2097152 rustcms serve</span></span></code></pre></div></div></div><h2 id="sources-and-precedence" tabindex="-1">Sources and precedence <a class="header-anchor" href="#sources-and-precedence" aria-label="Permalink to &quot;Sources and precedence&quot;">​</a></h2><p>Sources, last one wins:</p><ol><li>built-in defaults,</li><li><code>config/&lt;section&gt;.toml</code>: each file becomes the section named after it (<code>config/http.toml</code> is <code>[http]</code>); a missing file keeps the defaults,</li><li>well-known variables: <code>APP_NAME</code>, <code>APP_ENV</code>, <code>APP_DEBUG</code>, <code>APP_URL</code>, <code>APP_KEY</code>, <code>APP_PREVIOUS_KEYS</code>, <code>DATABASE_URL</code>, <code>REDIS_URL</code>,</li><li><code>RUSTCMS_&lt;SECTION&gt;__&lt;KEY&gt;</code>, e.g. <code>RUSTCMS_HTTP__BODY_LIMIT=2097152</code>.</li></ol><p><code>.env</code> is loaded first and never overrides variables already set in the environment. <code>config/</code> is read from the working directory; <code>.env</code> is looked for in the working directory, then in its parents.</p><h2 id="framework-sections" tabindex="-1">Framework sections <a class="header-anchor" href="#framework-sections" aria-label="Permalink to &quot;Framework sections&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>app.name</code></td><td><code>rustcms</code></td><td>the default Redis prefix is <code>rustcms:&lt;app.name&gt;</code></td></tr><tr><td><code>app.env</code></td><td><code>production</code></td><td><code>local</code>, <code>testing</code>, <code>production</code>: see <a href="#the-environment">The environment</a></td></tr><tr><td><code>app.debug</code></td><td><code>false</code></td><td>read by your code only: see <a href="#the-environment">The environment</a></td></tr><tr><td><code>app.url</code></td><td><code>http://localhost:8000</code></td><td>public URL; its origin may change state in the panel by default</td></tr><tr><td><code>app.key</code></td><td>— (<strong>required</strong>)</td><td><code>base64:</code> + 32 bytes; <code>rustcms key:generate</code></td></tr><tr><td><code>app.previous_keys</code></td><td><code>[]</code></td><td>keys <code>APP_KEY</code> replaced, only to open <a href="./../digging-deeper/encryption.html">encrypted values</a> until <code>key:reencrypt</code> ran; env <code>APP_PREVIOUS_KEYS</code> (comma-separated)</td></tr><tr><td><code>app.listen</code></td><td><code>127.0.0.1:8000</code></td><td>address of <code>serve</code> (<code>serve --listen</code> overrides)</td></tr><tr><td><code>app.mode</code></td><td><code>full</code></td><td><code>api</code>: the application API only, no admin panel (<a href="./../digging-deeper/instances.html#api-mode">API mode</a>); <code>serve --api-only</code> overrides</td></tr><tr><td><code>app.locale</code></td><td><code>en</code></td><td>admin interface language by default (<a href="./../admin/i18n.html">Languages</a>); must be one of <code>app.locales</code></td></tr><tr><td><code>app.locales</code></td><td><code>[&quot;en&quot;, &quot;vi&quot;]</code></td><td>languages users may choose (the panel ships <code>en</code>, <code>vi</code>)</td></tr><tr><td><code>database.url</code></td><td>— (<strong>required</strong>)</td><td><code>sqlite://…</code>, <code>postgres://…</code> or <code>mysql://…</code> (<a href="./../basics/database.html#mysql">MySQL setup</a>)</td></tr><tr><td><code>database.max_connections</code></td><td><code>10</code></td><td>pool size</td></tr><tr><td><code>database.log_statements</code></td><td><code>false</code></td><td>logs every SQL statement, at info level</td></tr><tr><td><code>database.allow_newer_migrations</code></td><td><code>false</code></td><td><code>migrate</code> accepts migrations a newer version applied (rollbacks; <a href="./deployment.html#upgrading">additive migrations only</a>)</td></tr><tr><td><code>http.body_limit</code></td><td><code>1048576</code></td><td>bytes; larger bodies get 413</td></tr><tr><td><code>http.timeout_secs</code></td><td><code>30</code></td><td>slower requests get 408</td></tr><tr><td><code>http.trusted_proxies</code></td><td><code>[]</code></td><td>CIDRs allowed to set <code>X-Forwarded-For</code> (<a href="./../architecture/lifecycle.html#client-ip-and-proxies">Client IP</a>)</td></tr><tr><td><code>log.filter</code></td><td><code>info</code></td><td>a <code>tracing</code> filter (<code>info,blog=debug</code>); <code>RUST_LOG</code> overrides</td></tr><tr><td><code>log.json</code></td><td><code>false</code></td><td>JSON lines for log shippers</td></tr></tbody></table><p>Loading fails with a message naming the key when <code>APP_KEY</code> is missing or malformed, when a previous key repeats another key, or when <code>app.locale</code> is not one of <code>app.locales</code> (tags such as <code>en</code>, <code>vi</code>).</p><p>New applications start from these files (the rest are defaults):</p><details class="details custom-block"><summary>The generated <code>config/</code> files</summary><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># config/app.toml (overridden by APP_* variables in .env)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;blog&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">listen = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;127.0.0.1:8000&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># &quot;api&quot;: the application API only, without the admin panel (`serve --api-only`).</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># mode = &quot;full&quot;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># config/auth.toml</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">admin_path = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/admin&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">admin_origins = []</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">session_lifetime_minutes = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">120</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">password_min_length = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">revoke_tokens_on_password_change = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># config/http.toml</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">body_limit = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1048576</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">timeout_secs = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">trusted_proxies = []</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># config/log.toml (RUST_LOG overrides it)</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">filter = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;info,blog=debug&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">json = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div></details><h3 id="storage-configstoragetoml" tabindex="-1"><code>[storage]</code> (<code>config/storage.toml</code>) <a class="header-anchor" href="#storage-configstoragetoml" aria-label="Permalink to &quot;`[storage]` (`config/storage.toml`)&quot;">​</a></h3><p>Uploads and the media library: see <a href="./../digging-deeper/storage.html">File storage</a>.</p><h3 id="auth-configauthtoml" tabindex="-1"><code>[auth]</code> (<code>config/auth.toml</code>) <a class="header-anchor" href="#auth-configauthtoml" aria-label="Permalink to &quot;`[auth]` (`config/auth.toml`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th></th></tr></thead><tbody><tr><td><code>auth.admin_path</code></td><td><code>/admin</code></td><td>panel and session guard prefix, cookie path</td></tr><tr><td><code>auth.admin_origins</code></td><td><code>[]</code> → <code>APP_URL</code></td><td>origins allowed to change state</td></tr><tr><td><code>auth.cookie_name</code></td><td><code>rustcms_session</code></td><td></td></tr><tr><td><code>auth.secure_cookies</code></td><td>https <code>APP_URL</code></td><td>unset: <code>Secure</code> cookies when <code>APP_URL</code> is https</td></tr><tr><td><code>auth.session_lifetime_minutes</code></td><td><code>120</code></td><td>idle, sliding</td></tr><tr><td><code>auth.anonymous_session_lifetime_minutes</code></td><td><code>15</code></td><td>sessions holding only a CSRF token</td></tr><tr><td><code>auth.anonymous_sessions_per_ip</code></td><td><code>30</code></td><td>new anonymous sessions per IP per minute</td></tr><tr><td><code>auth.anonymous_sessions_per_minute</code></td><td><code>1000</code></td><td>new anonymous sessions per minute, total</td></tr><tr><td><code>auth.password_min_length</code></td><td><code>8</code></td><td></td></tr><tr><td><code>auth.revoke_tokens_on_password_change</code></td><td><code>true</code></td><td></td></tr><tr><td><code>auth.attempts_per_identifier</code></td><td><code>5</code></td><td>failed sign-ins per account+IP per minute</td></tr><tr><td><code>auth.attempts_per_ip</code></td><td><code>30</code></td><td>failed sign-ins per IP per minute</td></tr><tr><td><code>auth.permission_cache_ttl_secs</code></td><td><code>30</code></td><td>upper bound; changes apply on the next request (on other instances within <code>permission_generation_cache_ms</code> when set)</td></tr><tr><td><code>auth.permission_generation_cache_ms</code></td><td><code>0</code></td><td>0–60,000, opt-in: how long the RBAC counter is reused; other instances see a change within it (0: read every request)</td></tr><tr><td><code>auth.remember_days</code></td><td><code>30</code></td><td>&quot;Remember me&quot; keeps a session this long (0: no such box)</td></tr><tr><td><code>auth.password_reset</code></td><td><code>false</code></td><td>&quot;Forgot password?&quot; (needs mail)</td></tr><tr><td><code>auth.password_reset_minutes</code></td><td><code>60</code></td><td>how long a reset link works</td></tr><tr><td><code>auth.invitation_days</code></td><td><code>7</code></td><td>how long an invitation link works (1–30)</td></tr><tr><td><code>auth.reset_requests_per_ip</code></td><td><code>5</code></td><td>reset requests per IP per minute</td></tr><tr><td><code>auth.reset_requests_per_email</code></td><td><code>3</code></td><td>reset requests per address per minute</td></tr><tr><td><code>auth.reset_cooldown_secs</code></td><td><code>60</code></td><td>at most one reset mail per user this often</td></tr><tr><td><code>auth.jwt.enabled</code></td><td><code>true</code></td><td>JWT sign-in endpoints and bearer JWTs</td></tr><tr><td><code>auth.jwt.session_cache_ms</code></td><td><code>0</code></td><td>0–60,000, opt-in: how long a JWT&#39;s sign-in is reused; other instances see a sign-out within it</td></tr><tr><td><code>auth.jwt.access_ttl_secs</code></td><td><code>900</code></td><td>access token lifetime (60–3600)</td></tr><tr><td><code>auth.jwt.refresh_ttl_days</code></td><td><code>14</code></td><td>an unused refresh token expires (1–90)</td></tr><tr><td><code>auth.jwt.refresh_family_days</code></td><td><code>30</code></td><td>a sign-in ends, however often refreshed (≥ refresh_ttl_days, ≤ 365)</td></tr></tbody></table><ul><li><code>auth.admin_path</code> is one or more segments of letters, digits, <code>_</code> and <code>-</code> (<code>/admin</code>, <code>/back-office/panel</code>); a trailing <code>/</code> is removed. <code>/</code> and paths under <code>/api</code> are refused.</li><li>A value out of its range (<code>invitation_days</code>, the <code>jwt</code> lifetimes) or a bad <code>admin_path</code> stops the application as soon as it is assembled, with a message naming the key: every command that assembles it fails (all but <code>key:generate</code>, <code>migrate</code>, <code>migrate:rollback</code>, <code>migrate:refresh</code>, <code>migrate:status</code>, and <code>migrate:fresh</code> without <code>--seed</code>).</li><li><code>auth.password_reset = true</code> without a mail driver stops the boot.</li></ul><p>See <a href="./../security/authentication.html">Authentication</a>.</p><h3 id="admin-configadmintoml" tabindex="-1"><code>[admin]</code> (<code>config/admin.toml</code>) <a class="header-anchor" href="#admin-configadmintoml" aria-label="Permalink to &quot;`[admin]` (`config/admin.toml`)&quot;">​</a></h3><p><a href="./../admin/customizing.html#runtime-branding">Runtime branding</a> of the panel.</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th></th></tr></thead><tbody><tr><td><code>admin.branding</code></td><td><code>&quot;runtime&quot;</code></td><td><code>&quot;static&quot;</code> ignores the <code>BrandingSource</code> (recovery: <code>RUSTCMS_ADMIN__BRANDING=static</code>)</td></tr><tr><td><code>admin.branding_ttl_secs</code></td><td><code>30</code></td><td>how long an instance keeps the loaded branding (1–3600)</td></tr><tr><td><code>admin.branding_timeout_ms</code></td><td><code>2000</code></td><td>a slower load shows the static theme (1–30000)</td></tr></tbody></table><h3 id="audit-configaudittoml" tabindex="-1"><code>[audit]</code> (<code>config/audit.toml</code>) <a class="header-anchor" href="#audit-configaudittoml" aria-label="Permalink to &quot;`[audit]` (`config/audit.toml`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th></th></tr></thead><tbody><tr><td><code>audit.retention_days</code></td><td><code>365</code></td><td>older entries are deleted hourly (1–36,500)</td></tr><tr><td><code>audit.sign_in_failures_per_minute</code></td><td><code>600</code></td><td>failed sign-ins recorded one by one, per instance</td></tr></tbody></table><p>See <a href="./../digging-deeper/audit-log.html">Audit log</a>.</p><h3 id="mail-configmailtoml-feature-mail" tabindex="-1"><code>[mail]</code> (<code>config/mail.toml</code>, feature <code>mail</code>) <a class="header-anchor" href="#mail-configmailtoml-feature-mail" aria-label="Permalink to &quot;`[mail]` (`config/mail.toml`, feature `mail`)&quot;">​</a></h3><p>Driver (<code>disabled</code>, <code>smtp</code>, <code>log</code>, <code>memory</code>), where the SMTP server comes from (<code>settings</code> or <code>config</code>), the hosts and ports mail may go to, timeouts and the rate: see <a href="./../digging-deeper/mail.html#configuration">Mail</a>.</p><h3 id="queue-configqueuetoml" tabindex="-1"><code>[queue]</code> (<code>config/queue.toml</code>) <a class="header-anchor" href="#queue-configqueuetoml" aria-label="Permalink to &quot;`[queue]` (`config/queue.toml`)&quot;">​</a></h3><p>Workers and job leases: see <a href="./../digging-deeper/queues.html#configuration">Queues</a>. <code>serve</code> runs <code>queue.workers</code> workers (2) when <code>queue.enabled</code> (left out: <code>true</code>, or <code>false</code> in <a href="./../digging-deeper/instances.html#api-mode">API mode</a>).</p><h3 id="redis-configredistoml-feature-redis" tabindex="-1"><code>[redis]</code> (<code>config/redis.toml</code>, feature <code>redis</code>) <a class="header-anchor" href="#redis-configredistoml-feature-redis" aria-label="Permalink to &quot;`[redis]` (`config/redis.toml`, feature `redis`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th></th></tr></thead><tbody><tr><td><code>redis.url</code></td><td>— (<code>REDIS_URL</code>)</td><td>standalone Redis; unset: one instance</td></tr><tr><td><code>redis.prefix</code></td><td><code>rustcms:&lt;app.name&gt;</code></td><td>shared by one deployment&#39;s instances, distinct between deployments; not empty, no spaces</td></tr></tbody></table><p>With a URL set, boot fails if Redis does not answer within 5 s, or if RustCMS was built without the <code>redis</code> feature. Commands time out after 1 s; rate limits then fail closed (500). See <a href="./../digging-deeper/instances.html">Several instances</a>.</p><h3 id="realtime-configrealtimetoml" tabindex="-1"><code>[realtime]</code> (<code>config/realtime.toml</code>) <a class="header-anchor" href="#realtime-configrealtimetoml" aria-label="Permalink to &quot;`[realtime]` (`config/realtime.toml`)&quot;">​</a></h3><p><a href="./../admin/realtime.html">Realtime</a> streams and sockets. Every limit is per instance; streams and sockets share <code>max_connections</code>, <code>max_per_user</code> and the open rates.</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th></th></tr></thead><tbody><tr><td><code>realtime.revalidate_secs</code></td><td><code>30</code></td><td>how often an open stream rechecks the session, user and permissions (at least 1; each check costs about 3 queries)</td></tr><tr><td><code>realtime.max_connections</code></td><td><code>1000</code></td><td>open streams on this instance (429 beyond)</td></tr><tr><td><code>realtime.max_per_user</code></td><td><code>10</code></td><td>open streams of one user on this instance</td></tr><tr><td><code>realtime.opens_per_user_per_minute</code></td><td><code>60</code></td><td></td></tr><tr><td><code>realtime.opens_per_ip_per_minute</code></td><td><code>300</code></td><td>shared IPs (offices, proxies) share it</td></tr><tr><td><code>realtime.shutdown_grace_secs</code></td><td><code>5</code></td><td>time given to open streams, sockets and connections when the server stops (<a href="./../architecture/lifecycle.html#stopping">Stopping</a>)</td></tr><tr><td><code>realtime.socket_revalidate_secs</code></td><td><code>10</code></td><td>how often an open WebSocket rechecks (at least 1)</td></tr><tr><td><code>realtime.max_message_bytes</code></td><td><code>65536</code></td><td>largest WebSocket message, either way (1009 beyond; at most 1 MiB); the panel&#39;s pages refuse to send larger ones (a tab keeps the value it loaded). Keep it the same on every instance</td></tr><tr><td><code>realtime.send_timeout_secs</code></td><td><code>10</code></td><td>longest wait of a WebSocket send for a slow client (then <code>lagging</code>; at least 1)</td></tr></tbody></table><p>Values below the minimum, or above the maximum, are raised or lowered to it.</p><h3 id="schedule-configscheduletoml" tabindex="-1"><code>[schedule]</code> (<code>config/schedule.toml</code>) <a class="header-anchor" href="#schedule-configscheduletoml" aria-label="Permalink to &quot;`[schedule]` (`config/schedule.toml`)&quot;">​</a></h3><p><a href="./../digging-deeper/scheduling.html">Scheduling</a>. Schedules run automatically in <code>serve</code> only; <code>schedule:run &lt;name&gt;</code> runs one by hand.</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th></th></tr></thead><tbody><tr><td><code>schedule.enabled</code></td><td><code>true</code> (<code>false</code> in <a href="./../digging-deeper/instances.html#api-mode">API mode</a>)</td><td>run the schedules on this instance</td></tr><tr><td><code>schedule.grace_secs</code></td><td><code>30</code></td><td>how late (1–300 s) a slot may still be claimed; older slots are skipped</td></tr><tr><td><code>schedule.history_retention_days</code></td><td><code>7</code></td><td>runs kept on the Schedules page (1–3,650)</td></tr></tbody></table><h2 id="the-environment" tabindex="-1">The environment <a class="header-anchor" href="#the-environment" aria-label="Permalink to &quot;The environment&quot;">​</a></h2><p><code>app.env</code> (<code>APP_ENV</code>) names where the application runs: <code>local</code>, <code>testing</code> or <code>production</code> (the default, so a server that forgets it gets the safe behaviour). The framework uses it in a few places:</p><table tabindex="0"><thead><tr><th>Behaviour</th><th><code>local</code></th><th><code>testing</code></th><th><code>production</code></th></tr></thead><tbody><tr><td><code>migrate:fresh</code>, <code>migrate:refresh</code>, <code>db:seed</code></td><td>run</td><td>run</td><td>refuse without <code>--force</code></td></tr><tr><td><code>mail.log_body</code> (mail bodies, reset links, in the log)</td><td>allowed</td><td>refused at start</td><td>refused at start</td></tr><tr><td><code>mail.allowed_hosts</code> when admins set the SMTP server (<code>smtp</code> driver)</td><td>optional</td><td>optional</td><td>required</td></tr><tr><td>Page and mail templates re-read from disk on each render</td><td>in debug builds (<code>cargo run</code>)</td><td>no</td><td>no</td></tr></tbody></table><p>Your code reads it as <code>state.config().app.env</code>, an <code>Environment</code> (<code>rustcms::config::Environment::{Local, Testing, Production}</code>), e.g. a seeder that refuses to create demo users in production.</p><p><code>app.debug</code> (<code>APP_DEBUG</code>, <code>true</code> in a new <code>.env</code>) is loaded for your code as <code>config.app.debug</code>. <strong>The framework does not change its behaviour on it</strong>: error responses never contain internal details, whatever its value, and log verbosity comes from <code>log.filter</code>. Keep it <code>false</code> in production anyway, in case your own code uses it.</p><h2 id="your-own-sections" tabindex="-1">Your own sections <a class="header-anchor" href="#your-own-sections" aria-label="Permalink to &quot;Your own sections&quot;">​</a></h2><p>Any <code>config/&lt;name&gt;.toml</code> becomes a section your code reads with <code>Config::section</code>. Pick a name the framework does not use (above):</p><div class="language-rust vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">#[derive(serde</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">::</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Deserialize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)]</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Billing</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { currency</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// in a provider&#39;s register: config/billing.toml or RUSTCMS_BILLING__CURRENCY</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> billing</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Billing</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> app</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">config</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">section</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;billing&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">expect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;[billing] settings&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p><code>section</code> deserializes with serde: give fields <code>#[serde(default)]</code> to make them optional. The configuration is available as <code>app.config()</code> while the application is assembled and as <code>state.config()</code> afterwards.</p><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><p>Every key can be set from the environment as <code>RUSTCMS_&lt;SECTION&gt;__&lt;KEY&gt;</code> (nested keys with more <code>__</code>): <code>RUSTCMS_APP__LISTEN=0.0.0.0:8000</code>, <code>RUSTCMS_AUTH__JWT__ACCESS_TTL_SECS=600</code>. Lists are written in TOML syntax: <code>RUSTCMS_HTTP__TRUSTED_PROXIES=&#39;[&quot;10.0.0.0/8&quot;]&#39;</code>. With every value in the environment, the <code>config/</code> directory is optional.</p><h3 id="from-files-docker-and-kubernetes-secrets" tabindex="-1">From files (Docker and Kubernetes secrets) <a class="header-anchor" href="#from-files-docker-and-kubernetes-secrets" aria-label="Permalink to &quot;From files (Docker and Kubernetes secrets)&quot;">​</a></h3><p>Any of these variables (the well-known ones and every <code>RUSTCMS_…</code>) can be read from a file instead: add <code>_FILE</code> to its name and give the path.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> APP_KEY_FILE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/run/secrets/app_key</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DATABASE_URL_FILE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/run/secrets/database_url</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> RUSTCMS_MAIL__SMTP__PASSWORD_FILE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/run/secrets/smtp_password</span></span></code></pre></div><ul><li>The value takes its variable&#39;s place in the order above: a <code>RUSTCMS_DATABASE__URL</code> still wins over <code>DATABASE_URL_FILE</code>.</li><li>One trailing line break is removed (as <code>echo</code> and editors add it); any other whitespace is kept. Values are read like environment values (<code>true</code>, numbers), except that a value with leading or trailing spaces stays exactly that string.</li><li>Boot fails when a variable and its <code>_FILE</code> are both set, or when the file is missing, unreadable, empty, not UTF-8 or larger than 64 KiB. The message names the variable and the path, never the content.</li><li>A key whose own name ends in <code>_file</code> cannot be set from the environment (<code>RUSTCMS_X__LOG_FILE</code> means the file of <code>x.log</code>); put it in a TOML file. A key named <code>file</code> itself is fine: <code>RUSTCMS_LOG__FILE</code> is <code>log.file</code>.</li></ul><h2 id="in-tests-and-tools" tabindex="-1">In tests and tools <a class="header-anchor" href="#in-tests-and-tools" aria-label="Permalink to &quot;In tests and tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>API</th><th>Does</th></tr></thead><tbody><tr><td><code>Config::load()</code></td><td>what the console does: <code>.env</code>, then <code>config/</code> and the environment of the working directory</td></tr><tr><td><code>Config::figment(dir)</code></td><td>the layered sources of <code>dir</code> and the environment, without <code>.env</code></td></tr><tr><td><code>Config::from_figment(figment)</code></td><td>checks and extracts the framework sections</td></tr><tr><td><code>config.with(&quot;app.env&quot;, &quot;production&quot;)</code></td><td>consumes the configuration and returns it with one value replaced, checked again (<code>Result&lt;Config, ConfigError&gt;</code>)</td></tr><tr><td><code>config.section::&lt;T&gt;(&quot;name&quot;)</code></td><td>an application section</td></tr></tbody></table><p>In tests, <code>rustcms_testing::test_config(url)</code> builds a configuration for a test database; change it with <code>with</code> (<a href="./../basics/testing.html">Testing</a>).</p><h2 id="pitfalls" tabindex="-1">Pitfalls <a class="header-anchor" href="#pitfalls" aria-label="Permalink to &quot;Pitfalls&quot;">​</a></h2><ul><li><strong>A section named like the framework&#39;s</strong> (<code>mail</code>, <code>queue</code>, <code>storage</code>, …) is the framework&#39;s: your fields and its fields must agree, and its checks apply.</li><li><strong><code>.env</code> does not override</strong> a variable already exported in the shell or by systemd: the environment wins.</li><li><strong>Secrets in <code>config/*.toml</code></strong> end up in the repository. Keep <code>APP_KEY</code>, database passwords and SMTP passwords in the environment or in <code>_FILE</code> secrets.</li></ul><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./deployment.html">Deployment</a>: what the binary reads on a server</li><li><a href="./../security/production.html">Production checklist</a></li><li><a href="./../operations/app-key.html">The <code>APP_KEY</code></a>: rotating it</li></ul>',62)])])}const g=t(s,[["render",i]]);export{u as __pageData,g as default};
